package com.yourapp.drama.workflow;
import com.fasterxml.jackson.databind.node.*; import com.yourapp.drama.persistence.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional; import static com.yourapp.drama.persistence.ResourceKind.*; import static com.yourapp.drama.workflow.Documents.*; import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class CharacterStateResolverTest { @Autowired DocumentStore store; @Autowired CharacterStateResolver states; @Test void characterStateUsesHistoricalAge(){ObjectNode p=store.create(PROJECT,obj().put("name","人物状态").put("idea","回忆"));ObjectNode c=store.create(ResourceKind.CHARACTER,obj().put("projectId",id(p)).put("name","主角"));ObjectNode young=obj().put("projectId",id(p)).put("characterId",id(c)).put("validFromStoryTime",1).put("validToStoryTime",30);young.set("state",obj().put("age",20));store.create(CHARACTER_STATE,young);ObjectNode old=obj().put("projectId",id(p)).put("characterId",id(c)).put("validFromStoryTime",30);old.set("state",obj().put("age",50));store.create(CHARACTER_STATE,old);assertThat(states.resolve(id(p),id(c),10).path("state").path("age").asInt()).isEqualTo(20);assertThat(states.resolve(id(p),id(c),40).path("state").path("age").asInt()).isEqualTo(50);}}
